# https://www.klinikpenyesalan.com/

  .hm-list .hm-row + .hm-row{border-top:1px solid var(--line);}
  .hm-list .hm-row:hover{background:var(--surface);}
  /* the featured (hovered) ticker block is tinted by direction: green up, red down */
  .hm-feat.up{background:#2e9e5b;}
  .hm-feat.down{background:#e5484d;}
  .hm-feat.up,.hm-feat.down{color:#fff;}
  .hm-feat.up .hm-row-c,.hm-feat.down .hm-row-c,
  .hm-feat.up .hm-row-p,.hm-feat.down .hm-row-p{color:#fff !important;}
  .hm-feat.up .hm-feat-name,.hm-feat.down .hm-feat-name{color:rgba(255,255,255,.82);}
  .hm-feat.up .hm-sp polyline,.hm-feat.down .hm-sp polyline{stroke:#fff !important;}
  .hm-tile-spark{fill:none;stroke:rgba(255,255,255,.5);stroke-width:1.1;vector-effect:non-scaling-stroke;pointer-events:none;}
  .hm-row-t{font-weight:600;width:48px;flex:none;}
  .hm-row-p{width:66px;text-align:right;color:var(--dim);flex:none;}
  .hm-row-c{width:56px;text-align:right;font-weight:600;flex:none;}
  .hm-sp{flex:1;min-width:18px;display:block;}

  /* hover crosshair + readout (cursor is set in JS once live data renders) */
  #fg-cursor{pointer-events:none;transition:opacity .12s ease;}
  .fg-cross{stroke:var(--line-2);stroke-width:1;vector-effect:non-scaling-stroke;}
  .fg-cross-fg{fill:var(--accent);stroke:var(--surface);stroke-width:2;}
  .fg-cross-jci{fill:var(--jci-line);stroke:var(--surface);stroke-width:2;}
  .fg-tip{position:absolute;left:0;top:0;z-index:6;pointer-events:none;opacity:0;
    transition:opacity .12s ease;background:var(--surface-2);border:1px solid var(--line-2);
    box-shadow:var(--elev);padding:9px 11px;font-family:var(--mono);font-size:11px;
    color:var(--text);white-space:nowrap;}
  .fg-tip-date{color:var(--mute);font-size:9px;letter-spacing:.12em;margin-bottom:7px;}
  .fg-tip-row{display:flex;align-items:center;gap:8px;line-height:1.7;}
  .fg-tip-row b{font-weight:600;margin-left:auto;padding-left:16px;}
  .fg-tip-sw{width:9px;height:9px;border-radius:2px;display:inline-block;flex:none;}
  .fg-tip-sw.fg{background:var(--accent);}
  .fg-tip-sw.jci{background:var(--jci-line);}

  /* ---- newsletter ---- */
  .blog-head{display:flex;justify-content:space-between;align-items:flex-end;gap:36px;margin-bottom:48px;}
  .blog-head h2{font-size:clamp(34px,3.8vw,50px);font-weight:500;letter-spacing:-.02em;margin:22px 0 0;}
  .blog-head-side{display:grid;justify-items:end;gap:18px;max-width:31em;}
  .blog-head-side p{margin:0;color:var(--dim);font-size:16px;line-height:1.6;font-weight:300;text-align:right;}
  .blog-head-side a{font-family:var(--mono);font-size:11px;letter-spacing:.09em;color:var(--accent);text-decoration:none;}
  .blog-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;}
  .blog-card{display:flex;flex-direction:column;border:1px solid var(--line);background:var(--surface);text-decoration:none;color:inherit;box-shadow:var(--elev);}
  .blog-card:hover{transform:translateY(-4px);border-color:var(--line-2);box-shadow:var(--elev-hi);}
  .blog-card-image{height:210px;background:var(--surface-2) center/cover no-repeat;border-bottom:1px solid var(--line);}
  .blog-card-image--empty{display:grid;place-items:center;background:linear-gradient(145deg,var(--surface),var(--bg));}
  .blog-card-image--empty span{font-family:var(--mono);font-size:11px;letter-spacing:.15em;color:var(--accent);}
  .blog-card-body{padding:25px;display:flex;flex:1;flex-direction:column;}
  .blog-card-meta{display:flex;justify-content:space-between;gap:12px;font-family:var(--mono);font-size:9.5px;letter-spacing:.1em;color:var(--mute);}
  .blog-card-meta span{color:var(--accent);}.blog-card-body h3{font-size:24px;line-height:1.16;font-weight:500;margin:19px 0 12px;}
  .blog-card-body p{font-size:14px;line-height:1.58;color:var(--dim);font-weight:300;margin:0 0 24px;flex:1;}
  .blog-card-open{padding-top:16px;border-top:1px solid var(--line);font-family:var(--mono);font-size:10px;letter-spacing:.08em;color:var(--accent);}
  .blog-empty{grid-column:1/-1;padding:56px;text-align:center;border:1px solid var(--line);background:var(--surface);}
  .blog-empty span{font-family:var(--mono);font-size:11px;letter-spacing:.12em;color:var(--accent);}.blog-empty p{color:var(--dim);margin:15px 0 0;}

  /* ---- responsive ---- */
  @media (max-width:900px){
    .hero-grid{grid-template-columns:1fr;gap:48px;padding:72px 32px 84px;}
    .apps-grid{grid-template-columns:1fr;}
    .floor-grid{grid-template-columns:1fr;}
    .floor-social{flex-direction:row;border-left:0;border-top:1px solid var(--line);}
    .social-cell + .social-cell{border-top:0;border-left:1px solid var(--line);}
    .fg-grid{grid-template-columns:1fr;}
    .blog-grid{grid-template-columns:repeat(2,minmax(0,1fr));}
  }
  @media (max-width:760px){
    nav.main .nav-link{display:none;}
    .fg-chart .ax{font-size:16px;}
    .fg-chart .m-odd{display:none;}
  }
  @media (max-width:620px){
    .wrap{padding:0 20px;}
    .hero-grid,.section-inner,.header-inner,.footer-inner{padding-left:20px;padding-right:20px;}
    .section-inner{padding-top:64px;padding-bottom:68px;}
    .apps-head{flex-direction:column;align-items:flex-start;}
    .floor-main{padding:40px 28px;}
    .social-cell{padding:28px;}
    .floor-social{flex-direction:column;}
    .social-cell + .social-cell{border-top:1px solid var(--line);border-left:0;}
    .header-inner{height:62px;}
    .toggle,header .btn{min-height:44px;}
    .fg-chart .ax{font-size:21px;}
    .fg-chart .m-sm{display:none;}
    .apps-head{margin-bottom:36px;gap:16px;}
    .fg-meter-body{padding:26px 22px 26px;gap:16px;}
    .fg-stats{padding-top:18px;}
    .fg-chart-body{padding:20px 16px 16px;}
    .blog-head{align-items:flex-start;flex-direction:column;}.blog-head-side{justify-items:start;}.blog-head-side p{text-align:left;}
    .blog-grid{grid-template-columns:1fr;}.blog-card-image{height:230px;}
  }
  @media (max-width:520px){
    .brand .name{display:none;}
  }
  @media (prefers-reduced-motion:reduce){
    .ticker-track,.terminal-head .live .dot,.terminal-prompt .caret,.reveal,
    .bars span,.ipo-bars span,.ff-locked{animation:none;}
    .meter>span::after,.ff-fill::after{display:none;}
    [data-kp-root] *{transition:none;}
  }
</style>
<script type="application/ld+json">
