<header class="site">
  <div class="wrap header-inner">
    <a class="brand" href="#top">
      <svg class="kp-logo" style="height:24px" viewBox="0 0 600 499" role="img" aria-label="Klinik Penyesalan"><use href="#kp-mark"/></svg>
      <span class="name">KLINIK&nbsp;PENYESALAN</span>
    </a>
    <nav class="main">
      <a class="nav-link" href="#apps">TOOLS</a>
      <a class="nav-link" href="#sentiment">SENTIMENT</a>
      <a class="nav-link" href="#heatmap">HEATMAP</a>
      <a class="nav-link" href="#newsletter">NEWSLETTER</a>
      <a class="nav-link" href="#community">COMMUNITY</a>
      <button class="toggle" id="theme-toggle" type="button" aria-label="Switch to light mode" title="Switch to light mode" aria-pressed="false"><i class="fa-solid fa-sun" aria-hidden="true"></i></button>
      <a class="btn btn--primary" style="padding:12px 18px;font-size:11px;margin-left:4px" href="https://discord.gg/kpkp88" target="_blank" rel="noopener">JOIN DISCORD →</a>
    </nav>
  </div>
</header>

<!-- ticker -->
<div class="ticker">
  <div class="ticker-track">
    <div class="ticker-group">
      <span class="kp-jci"></span>
      <span class="kp-fg"></span>
      <span><span class="up">▲</span>&nbsp; STOCK TRANSACTION ANALYSIS</span>
      <span><span class="up">▲</span>&nbsp; IPO ANALYTICS</span>
      <span><span class="up">▲</span>&nbsp; 1% SHAREHOLDERS DATA</span>
      <span><span class="up">▲</span>&nbsp; FREE-FLOAT DATA</span>
      <span>IDX · JAKARTA</span>
      <span><span class="up">▲</span>&nbsp; JOIN THE DISCORD</span>
    </div>
    <div class="ticker-group" aria-hidden="true">
      <span class="kp-jci"></span>
      <span class="kp-fg"></span>
      <span><span class="up">▲</span>&nbsp; STOCK TRANSACTION ANALYSIS</span>
      <span><span class="up">▲</span>&nbsp; IPO ANALYTICS</span>
      <span><span class="up">▲</span>&nbsp; 1% SHAREHOLDERS DATA</span>
      <span><span class="up">▲</span>&nbsp; FREE-FLOAT DATA</span>
      <span>IDX · JAKARTA</span>
      <span><span class="up">▲</span>&nbsp; JOIN THE DISCORD</span>
    </div>
  </div>
</div>

<!-- hero -->
<section class="hero" id="top">
  <div class="hero-glow"></div>
  <div class="wrap hero-grid">
    <div>
      <div class="eyebrow reveal" style="margin-bottom:32px;animation-delay:.04s">INDONESIAN STOCK MARKET COMMUNITY</div>
      <h1 class="reveal" style="animation-delay:.10s">Where conviction meets the <span class="accent">order book.</span></h1>
      <p class="lede reveal" style="animation-delay:.16s">A community for Indonesian retail traders who'd rather read the data than chase tips. The tools are free, and they show what's under the price: broker flow, IPO demand, real ownership, free float. The rest happens on Discord.</p>
      <p class="mono-note reveal" style="animation-delay:.22s">// Trade less. Regret less.</p>
      <div class="cta reveal" style="animation-delay:.28s">
        <a class="btn btn--primary" href="https://discord.gg/kpkp88" target="_blank" rel="noopener">JOIN THE DISCORD →</a>
        <a class="btn btn--ghost" href="#apps">SEE THE TOOLS</a>
      </div>
      <div class="hero-live reveal" style="animation-delay:.34s">
        <span class="lbl">LIVE NOW //</span>
        <a class="live-chip" href="#sentiment"><span class="dot"></span>Fear &amp; Greed Index<span class="arr">↓</span></a>
        <a class="live-chip" href="#heatmap"><span class="dot"></span>IDX Market Heatmap<span class="arr">↓</span></a>
      </div>
    </div>

    <div class="reveal" style="display:flex;align-items:center;animation-delay:.20s">
      <div class="terminal">
        <div class="terminal-head">
          <span>KP://TERMINAL</span>
          <span class="live"><span class="dot"></span>LIVE</span>
        </div>
        <div class="terminal-body">
          <div class="terminal-logo">
            <svg class="kp-logo" style="height:70px" viewBox="0 0 600 499" aria-hidden="true"><use href="#kp-mark"/></svg>
          </div>
          <a class="app-row" href="https://arthara.id" target="_blank" rel="noopener">
            <span class="tag">ARTH</span><span class="label">Transaction Analysis</span><span class="arr">↗</span>
          </a>
          <a class="app-row" href="https://ipo.klinikpenyesalan.com" target="_blank" rel="noopener">
            <span class="tag">IPO</span><span class="label">IPO Analytics</span><span class="arr">↗</span>
          </a>
          <a class="app-row" href="https://1pct.klinikpenyesalan.com" target="_blank" rel="noopener">
            <span class="tag">1PCT</span><span class="label">1% Shareholders</span><span class="arr">↗</span>
          </a>
          <a class="app-row" href="https://ff.klinikpenyesalan.com" target="_blank" rel="noopener">
            <span class="tag">FF</span><span class="label">Free-Float Data</span><span class="arr">↗</span>
          </a>
          <div class="terminal-prompt">kp@idx:~$ <span class="caret">_</span></div>
        </div>
      </div>
    </div>
  </div>
</section>

<!-- tools -->
<section class="section" id="apps">
  <div class="wrap section-inner">
    <div class="apps-head">
      <div>
        <div class="eyebrow">TOOLS &amp; DATA</div>
        <h2>Built for the desk.</h2>
      </div>
      <p class="intro">Four free tools, each on its own subdomain. Pick one and dig in.</p>
    </div>

    <div class="apps-grid">

      <!-- 01 -->
      <a class="tool-card" href="https://arthara.id" target="_blank" rel="noopener">
        <div class="tool-viz">
          <div class="viz-head"><span>BROKER FLOW</span><span style="color:var(--accent)">arthara.id</span></div>
          <div class="bars">
            <span style="height:40%;background:var(--accent)"></span>
            <span style="height:62%;background:var(--accent)"></span>
            <span style="height:48%;background:var(--logo-light)"></span>
            <span style="height:78%;background:var(--accent)"></span>
            <span style="height:34%;background:var(--logo-light)"></span>
            <span style="height:90%;background:var(--accent)"></span>
            <span style="height:56%;background:var(--logo-light)"></span>
            <span style="height:70%;background:var(--accent)"></span>
            <span style="height:44%;background:var(--logo-light)"></span>
            <span style="height:64%;background:var(--accent)"></span>
            <span style="height:82%;background:var(--accent)"></span>
          </div>
          <div style="display:flex;gap:16px;font-family:var(--mono);font-size:10px">
            <span style="color:var(--accent)">BUY&nbsp; 12,400 ▲</span><span style="color:var(--dim)">SELL&nbsp; 9,100 ▼</span><span style="color:var(--mute)">NET +3,300</span>
          </div>
        </div>
        <div class="tool-body">
          <div class="row1"><span class="num">01</span><h3>Stock Transaction Analysis</h3></div>
          <p>See which brokers are loading up and which are dumping, counter by counter. Powered by Arthara.</p>
          <div class="foot"><span class="url">arthara.id</span><span class="open">OPEN →</span></div>
        </div>
      </a>

      <!-- 02 -->
      <a class="tool-card" href="https://ipo.klinikpenyesalan.com" target="_blank" rel="noopener">
        <div class="tool-viz">
          <div class="viz-head"><span>IPO PIPELINE / 2026</span><span style="color:var(--accent)">▲ 12 ACTIVE</span></div>
          <div class="ipo-bars" style="display:flex;align-items:flex-end;gap:9px;height:62px">
            <span style="flex:1;height:38%;background:var(--line-2)"></span>
            <span style="flex:1;height:60%;background:var(--line-2)"></span>
            <span style="flex:1;height:46%;background:var(--line-2)"></span>
            <span style="flex:1;height:78%;background:var(--line-2)"></span>
            <span style="flex:1;height:54%;background:var(--line-2)"></span>
            <span style="flex:1;height:100%;background:var(--accent)"></span>
          </div>
          <div style="display:flex;flex-direction:column;gap:8px">
            <div class="meter-row"><span style="width:42px">CDIA</span><span class="meter" style="height:5px"><span style="height:5px;width:82%"></span></span><span style="color:var(--mute)">82%</span></div>
            <div class="meter-row"><span style="width:42px">RATU</span><span class="meter" style="height:5px"><span style="height:5px;width:54%"></span></span><span style="color:var(--mute)">54%</span></div>
          </div>
        </div>
        <div class="tool-body">
          <div class="row1"><span class="num">02</span><h3>IPO Analytics</h3></div>
          <p>How every IDX IPO was priced and subscribed, and how it traded once the hype faded.</p>
          <div class="foot"><span class="url">ipo.klinikpenyesalan.com</span><span class="open">OPEN →</span></div>
        </div>
      </a>

      <!-- 03 -->
      <a class="tool-card" href="https://1pct.klinikpenyesalan.com" target="_blank" rel="noopener">
        <div class="tool-viz">
          <div class="viz-head"><span>OWNERSHIP &gt; 1.00%</span></div>
          <div style="display:flex;flex-direction:column;gap:11px">
            <div class="meter-row"><span style="width:72px">PT SARANA</span><span class="meter" style="height:9px"><span style="height:9px;width:88%"></span></span><span style="color:var(--mute);width:34px;text-align:right">5.12%</span></div>
            <div class="meter-row"><span style="width:72px">RG NOMINEE</span><span class="meter" style="height:9px"><span style="height:9px;width:62%"></span></span><span style="color:var(--mute);width:34px;text-align:right">3.41%</span></div>
            <div class="meter-row"><span style="width:72px">CITI NOM</span><span class="meter" style="height:9px"><span style="height:9px;width:40%;background:var(--accent-dim)"></span></span><span style="color:var(--mute);width:34px;text-align:right">2.18%</span></div>
            <div class="meter-row"><span style="width:72px">PUBLIC</span><span class="meter" style="height:9px"><span style="height:9px;width:24%;background:var(--accent-dim)"></span></span><span style="color:var(--mute);width:34px;text-align:right">1.07%</span></div>
          </div>
        </div>
        <div class="tool-body">
          <div class="row1"><span class="num">03</span><h3>1% Shareholders Data</h3></div>
          <p>When someone crosses the 1% ownership line, you see it the moment it's filed: who's building a position, who's getting out.</p>
          <div class="foot"><span class="url">1pct.klinikpenyesalan.com</span><span class="open">OPEN →</span></div>
        </div>
      </a>

      <!-- 04 -->
      <a class="tool-card" href="https://ff.klinikpenyesalan.com" target="_blank" rel="noopener">
        <div class="tool-viz">
          <div class="viz-head"><span>FREE FLOAT / BBRI</span></div>
          <div style="display:flex;align-items:baseline;gap:10px">
            <span style="font-size:54px;font-weight:500;line-height:.9;letter-spacing:-.02em">73.4</span>
            <span style="font-size:24px;color:var(--accent)">%</span>
          </div>
          <div>
            <div style="display:flex;height:13px;border:1px solid var(--line-2)">
              <span class="ff-fill" style="width:73.4%;background:var(--accent)"></span>
              <span class="ff-locked" style="flex:1;background:repeating-linear-gradient(45deg,var(--line),var(--line) 3px,transparent 3px,transparent 6px)"></span>
            </div>
            <div style="display:flex;justify-content:space-between;font-family:var(--mono);font-size:10px;color:var(--mute);margin-top:9px">
              <span><span style="color:var(--accent)">■</span> TRADABLE</span><span>■ LOCKED 26.6%</span>
            </div>
          </div>
        </div>
        <div class="tool-body">
          <div class="row1"><span class="num">04</span><h3>Free-Float Data</h3></div>
          <p>Know how much of a counter is really tradable before you size in and learn the hard way.</p>
          <div class="foot"><span class="url">ff.klinikpenyesalan.com</span><span class="open">OPEN →</span></div>
        </div>
      </a>

    </div>
  </div>
</section>

<!-- market sentiment: JCI Fear & Greed Index -->
<section class="section" id="sentiment">
  <div class="wrap section-inner">
    <div class="apps-head">
      <div>
        <div class="eyebrow">MARKET SENTIMENT</div>
        <h2>Fear &amp; Greed, vs the index.</h2>
      </div>
      <p class="intro">How fearful or greedy the tape is, scored 0&ndash;100 and tracked against the index. One year, daily.</p>
    </div>

    <div class="fg-grid">
      <!-- current reading -->
      <div class="fg-card">
        <div class="terminal-head">
          <span>FEAR &amp; GREED</span>
          <span class="fg-head-meta">SNAPSHOT</span>
        </div>
        <div class="fg-meter-body">
