<!-- Live Fear & Greed: fetch from same-origin proxy (/api/fear-greed) and repaint.
     Progressive enhancement: if the fetch fails, the baked snapshot stays. -->
<script>
  (function () {
    var MON = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
    // Gauge geometry (matches the baked SVG)
    var GCX = 130, GCY = 138, NEEDLE_R = 82;
    // Chart plot box (matches the baked SVG viewBox 0 0 1000 360)
    var PL = 58, PR = 948, PT = 26, PB = 312;

    function $(id) { return document.getElementById(id); }
    function labelFor(v) {
      return v < 25 ? 'Extreme Fear' : v < 45 ? 'Fear' : v < 55 ? 'Neutral' : v < 75 ? 'Greed' : 'Extreme Greed';
    }
    function colorFor(v) {
      return v < 25 ? '#e5484d' : v < 45 ? '#ef8e4b' : v < 55 ? '#dcc24a' : v < 75 ? '#5bb87a' : 'var(--accent)';
    }
    function fmtDate(iso) {
      var p = String(iso).slice(0, 10).split('-');
      if (p.length < 3) return '';
      return parseInt(p[2], 10) + ' ' + MON[parseInt(p[1], 10) - 1] + ' ' + p[0];
    }
    function esc(s) {
      return String(s).replace(/[&<>"']/g, function (c) {
        return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
      });
    }
    function niceNum(x, round) {
      var exp = Math.floor(Math.log10(x)), f = x / Math.pow(10, exp), nf;
      if (round) nf = f < 1.5 ? 1 : f < 3 ? 2 : f < 7 ? 5 : 10;
      else nf = f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10;
      return nf * Math.pow(10, exp);
    }
    function niceRange(min, max) {
      if (max <= min) max = min + 1;
      var step = niceNum(niceNum(max - min, false) / 4, true);
      var lo = Math.floor(min / step) * step, hi = Math.ceil(max / step) * step, ticks = [];
      for (var v = lo; v <= hi + 1e-6; v += step) ticks.push(Math.round(v));
      return { lo: lo, hi: hi, ticks: ticks };
    }

    function gauge(value) {
      var v = Math.max(0, Math.min(100, value));
      var a = Math.PI * (180 - v * 1.8) / 180;
      return [GCX + NEEDLE_R * Math.cos(a), GCY - NEEDLE_R * Math.sin(a)];
    }

    function buildChart(series) {
      var n = series.length;
      if (n < 2) return;
      var jvals = series.map(function (d) { return d.jci; });
      var r = niceRange(Math.min.apply(null, jvals), Math.max.apply(null, jvals));
      var x = function (i) { return PL + i / (n - 1) * (PR - PL); };
      var yJ = function (v) { return PB - (v - r.lo) / (r.hi - r.lo) * (PB - PT); };
      var yF = function (v) { return PB - v / 100 * (PB - PT); };
      var jp = [], fp = [];
      for (var i = 0; i < n; i++) {
        jp.push(x(i).toFixed(1) + ' ' + yJ(series[i].jci).toFixed(1));
        fp.push(x(i).toFixed(1) + ' ' + yF(series[i].fg).toFixed(1));
      }
      var area = 'M' + PL.toFixed(1) + ' ' + PB.toFixed(1) + ' L' + jp.join(' L') + ' L' + PR.toFixed(1) + ' ' + PB.toFixed(1) + ' Z';
      var jline = 'M' + jp.join(' L');
      var fline = 'M' + fp.join(' L');
      var lastF = fp[fp.length - 1].split(' ');

      var svg = '<rect class="fg-capture" x="' + PL + '" y="' + PT + '" width="' + (PR - PL) + '" height="' + (PB - PT) + '" fill="transparent" pointer-events="all"/>';
      svg += '<path class="fg-area" d="' + area + '"/>';
      svg += '<path class="fg-jline" d="' + jline + '"/>';
      svg += '<path class="fg-line" d="' + fline + '"/>';
      svg += '<circle class="fg-dot" cx="' + lastF[0] + '" cy="' + lastF[1] + '" r="4"/>';
      // left axis (JCI)
      r.ticks.forEach(function (t) {
        svg += '<text x="48" y="' + (yJ(t) + 3.5).toFixed(1) + '" class="ax ax-l">' + t.toLocaleString('en-US') + '</text>';
      });
      // right axis (Fear & Greed)
      [0, 25, 50, 75, 100].forEach(function (t) {
        svg += '<text x="958" y="' + (yF(t) + 3.5).toFixed(1) + '" class="ax ax-r">' + t + '</text>';
      });
      // month labels, density + min-gap based on viewport so they never crowd
      var sm = matchMedia('(max-width:620px)').matches, md = matchMedia('(max-width:760px)').matches;
      var font = sm ? 21 : md ? 16 : 12, minGap = font * 6 * 0.66, half = minGap / 2;
      var firsts = [], seen = {};
      for (var k = 0; k < n; k++) { var ym = series[k].date.slice(0, 7); if (!seen[ym]) { seen[ym] = 1; firsts.push(k); } }
      var m = firsts.length, lastC = -1e9, endC = PR - half;
      for (var j = 0; j < m; j++) {
        var idx = firsts[j], isFirst = j === 0, isLast = j === m - 1;
        var xx = isLast ? PR : x(idx);
        // effective visual center: first label is left-anchored, last is right-anchored
        var c = isLast ? endC : isFirst ? xx + half : xx;
        if (!isLast) {
          if (c - lastC < minGap) continue;     // clears the previous label
          if (endC - c < minGap) continue;       // leaves room for the final label
        }
        var dt = new Date(series[idx].date + 'T00:00:00Z');
        var lab = MON[dt.getUTCMonth()] + '-' + (String(dt.getUTCFullYear()).slice(2));
        var cls = 'ax ax-x' + (isFirst ? ' ax-x-first' : '') + (isLast ? ' ax-x-last' : '');
        svg += '<text x="' + xx.toFixed(1) + '" y="336" class="' + cls + '">' + lab + '</text>';
        lastC = c;
      }
      svg += '<g id="fg-cursor" opacity="0">' +
        '<line class="fg-cross" x1="0" y1="' + PT + '" x2="0" y2="' + PB + '"/>' +
        '<circle class="fg-cross-jci" r="4"/><circle class="fg-cross-fg" r="4.5"/></g>';
      var chartEl = $('fg-chart');
      chartEl.innerHTML = svg;
      chartEl.style.cursor = 'crosshair'; // becomes interactive only with live data
      chartState = { series: series, n: n, jLo: r.lo, jHi: r.hi };
    }

    // ---- hover crosshair + readout ----
    var chartState = null, hoverRaf = 0;
    function hideCursor() {
      if (hoverRaf) { cancelAnimationFrame(hoverRaf); hoverRaf = 0; }
      var g = $('fg-cursor'); if (g) g.setAttribute('opacity', '0');
      var t = $('fg-tip'); if (t) t.style.opacity = '0';
    }
    function showCursor(clientX, clientY) {
      var s = chartState; if (!s) return;
      var svg = $('fg-chart'), g = $('fg-cursor'), tip = $('fg-tip');
      if (!svg || !g || !tip) return;
      var rect = svg.getBoundingClientRect(); if (!rect.width) return;
      var i = Math.round(((clientX - rect.left) / rect.width * 1000 - PL) / (PR - PL) * (s.n - 1));
      i = Math.max(0, Math.min(s.n - 1, i));
      var cx = PL + (s.n > 1 ? i / (s.n - 1) : 0) * (PR - PL);
      var d = s.series[i], fg = d.fg, jci = d.jci;
      var yf = PB - fg / 100 * (PB - PT);
      var jSpan = s.jHi - s.jLo;
      var yj = jSpan ? PB - (jci - s.jLo) / jSpan * (PB - PT) : (PT + PB) / 2;
      var ln = g.children[0], dj = g.children[1], df = g.children[2];
      ln.setAttribute('x1', cx); ln.setAttribute('x2', cx);
      dj.setAttribute('cx', cx); dj.setAttribute('cy', yj.toFixed(1));
      df.setAttribute('cx', cx); df.setAttribute('cy', yf.toFixed(1));
      g.setAttribute('opacity', '1');
      var col = colorFor(fg), lab = labelFor(fg);
      tip.innerHTML = '<div class="fg-tip-date">' + esc(fmtDate(d.date)) + '</div>' +
        '<div class="fg-tip-row"><span class="fg-tip-sw fg"></span>F&amp;G<b style="color:' + col + '">' + fg + ' · ' + lab.toUpperCase() + '</b></div>' +
        '<div class="fg-tip-row"><span class="fg-tip-sw jci"></span>JCI<b>' + Math.round(jci).toLocaleString('en-US') + '</b></div>';
      var br = tip.parentElement.getBoundingClientRect();
      var px = rect.left - br.left + cx / 1000 * rect.width;
      var py = rect.top - br.top + yf / 360 * rect.height;
      tip.style.opacity = '1';
      var tw = tip.offsetWidth, th = tip.offsetHeight;
      var left = px + 16; if (left + tw > br.width - 4) left = px - tw - 16; if (left < 4) left = 4;
      var top = py - th - 14; if (top < 4) top = py + 18; if (top + th > br.height - 4) top = br.height - th - 4;
      tip.style.left = left.toFixed(0) + 'px'; tip.style.top = top.toFixed(0) + 'px';
    }
    function onMove(ev) {
      var t = ev.touches && ev.touches[0];
      var cx = t ? t.clientX : ev.clientX, cy = t ? t.clientY : ev.clientY;
      if (cx == null) return;
      if (hoverRaf) cancelAnimationFrame(hoverRaf);
      hoverRaf = requestAnimationFrame(function () { hoverRaf = 0; showCursor(cx, cy); });
    }
    (function bindHover() {
      var svg = $('fg-chart'); if (!svg) return;
      svg.addEventListener('mousemove', onMove);
      svg.addEventListener('mouseleave', hideCursor);
      svg.addEventListener('touchstart', onMove, { passive: true });
      svg.addEventListener('touchmove', onMove, { passive: true });
      svg.addEventListener('touchend', hideCursor);
    })();

    // header ticker: latest JCI + day-over-day change, and the F&G value
    function setTicker(series, cur) {
      if (!series.length) return;
      var js = document.querySelectorAll('.kp-jci'), fs = document.querySelectorAll('.kp-fg'), i;
      var fgHtml = 'FEAR &amp; GREED <b style="color:' + colorFor(cur) + '">' + Math.round(cur) + ' · ' + labelFor(cur).toUpperCase() + '</b>';
      for (i = 0; i < fs.length; i++) fs[i].innerHTML = fgHtml;
      if (series.length < 2) return; // need two closes for a day-over-day move; leave JCI slot hidden
      var n = series.length, last = series[n - 1].jci, prev = series[n - 2].jci;
      var pts = last - prev, pct = prev ? pts / prev * 100 : 0;
      var up = pts >= 0, cls = up ? 'up' : 'down', arr = up ? '▲' : '▼', sg = up ? '+' : '−';
      var jciHtml = 'JCI <b>' + Math.round(last).toLocaleString('en-US') + '</b> ' +
        '<b class="' + cls + '">' + arr + ' ' + sg + Math.abs(pct).toFixed(2) + '% · ' + sg + Math.abs(Math.round(pts)).toLocaleString('en-US') + '</b>';
      for (i = 0; i < js.length; i++) js[i].innerHTML = jciHtml;
    }

    function render(data) {
      if (!data || typeof data.current !== 'number' || !Array.isArray(data.series)) return;
      var v = data.current, col = colorFor(v), label = (data.label || labelFor(v));
      var valEl = $('fg-val'), clsEl = $('fg-cls'), gaugeEl = $('fg-gauge'), needle = $('fg-needle');
      if (valEl) { valEl.textContent = Math.round(v); valEl.style.color = col; }
      if (clsEl) { clsEl.textContent = label.toUpperCase(); clsEl.style.color = col; }
      if (needle) { var p = gauge(v); needle.setAttribute('x2', p[0].toFixed(1)); needle.setAttribute('y2', p[1].toFixed(1)); }
      if (gaugeEl) gaugeEl.setAttribute('aria-label', 'Fear and Greed gauge, current value ' + Math.round(v) + ' out of 100, ' + label.toLowerCase());
